#include "resident/checkpoint/checkpoint_decode_lifecycle.hpp"
#include "treaty_terms_codec_fields.hpp"
namespace hanmo::resident {
Status visit_safe_exit_terms(CodecVisitor& c,SafeExitTerms& r){if(!c.reading()){auto s=validate_safe_exit_terms_shape(r);if(!s.ok)return s;}auto s=treaty_terms_codec_fields::safe_exit(c,r);return s.ok?validate_safe_exit_terms_shape(r):s;}
Status visit_treaty_terms(CodecVisitor& c,TreatyTermsV1& r){if(!c.reading()){auto s=validate_treaty_terms_shape(r);if(!s.ok)return s;}auto s=treaty_terms_codec_fields::terms(c,r);return s.ok?validate_treaty_terms_shape(r):s;}
Status emit_treaty_terms_projection(ProjectionWriter& sink,std::string_view name,const TreatyTermsV1& r){auto s=validate_treaty_terms_shape(r);if(!s.ok)return s;return emit_projection_record<ActorFoundationProjectionArchive>(sink,name,r,[](auto& c,auto& v){return treaty_terms_codec_fields::terms(c,v);});}
Outcome<BoundaryValue> encode_treaty_terms(const TreatyTermsV1& r){BoundaryValue out;BoundaryProjectionWriter sink(out);auto s=emit_treaty_terms_projection(sink,"",r);if(s.ok)s=sink.finish();return {s.ok,std::move(out),s.error};}
Outcome<TreatyTermsV1> decode_treaty_terms(const BoundaryValue& input){TreatyTermsV1 out;ActorFoundationJsonVisitor reader(input);auto s=treaty_terms_codec_fields::terms(reader,out);if(s.ok)s=reader.finish();if(s.ok)s=validate_treaty_terms_shape(out);return {s.ok,std::move(out),s.error};}
Status emit_political_treaty_terms_catalog_projection(ProjectionWriter& sink,std::string_view name,const PoliticalTreatyTermsCatalog& r){for(const auto& row:r.definitions.rows()){if(row.first!=row.second.id||row.first.empty())return common_failure("InvalidTreatyTermsDefinition",row.first);auto s=validate_treaty_terms_shape(row.second.terms);if(!s.ok)return s;}return emit_projection_record<ActorFoundationProjectionArchive>(sink,name,r,[](auto& c,auto& v){return treaty_terms_codec_fields::catalog(c,v);});}
Outcome<BoundaryValue> encode_political_treaty_terms_catalog(const PoliticalTreatyTermsCatalog& r){BoundaryValue out;BoundaryProjectionWriter sink(out);auto s=emit_political_treaty_terms_catalog_projection(sink,"",r);if(s.ok)s=sink.finish();return {s.ok,std::move(out),s.error};}
Outcome<PoliticalTreatyTermsCatalog> decode_political_treaty_terms_catalog(const BoundaryValue& input,const CatalogIdentity& identity,const TreatyTermsOriginalRead& originals){PoliticalTreatyTermsCatalog out;out.identity=identity;ActorFoundationJsonVisitor reader(input);auto s=treaty_terms_codec_fields::catalog(reader,out);if(s.ok)s=reader.finish();if(s.ok)s=validate_political_treaty_terms_catalog(out,originals);return {s.ok,std::move(out),s.error};}
}
